export type NeonSystemMessageType = "error" | "info" | "warning" | "success";
export interface NeonSystemMessageDetail {
    href?: string;
    text?: string;
}
export interface NeonSystemMessageConfig {
    sendTo: string;
    autoDismiss?: boolean;
    autoDismissTime?: number;
    messageType?: NeonSystemMessageType | undefined;
    title?: string;
    dismissable?: boolean;
    announceText?: string;
}
export interface NeonSystemMessageEventDetail {
    controlConfig: NeonSystemMessageConfig;
    message: Array<NeonSystemMessageDetail> | string;
    idCreatedCallback?: (id: string) => void;
}
